mapper.select:
SELECT  FROM user_account u LEFT JOIN korus_staff_snapshot k ON k.staff_no = u.staff_no LEFT JOIN organization o ON o.organization_code = k.organization_code LEFT JOIN user_role ur ON ur.user_id = u.user_id AND ur.status='ACTIVE' AND ur.use_yn='Y'

  u.deleted_at IS NULL
  AND k.staff_no LIKE CONCAT('%', #{f.staffNo}, '%')
  AND k.staff_name LIKE CONCAT('%', #{f.name}, '%')
  AND k.organization_code = #{f.organizationCode}
  AND k.job_title = #{f.position}
  AND k.employment_status = #{f.employmentStatus}
  AND u.use_yn = #{f.useYn}
  AND EXISTS (SELECT 1 FROM user_role rx WHERE rx.user_id=u.user_id AND rx.role_code=#{f.roleCode} AND rx.status='ACTIVE' AND rx.use_yn='Y')

GROUP BY u.user_id, u.login_id, u.display_name, u.use_yn, u.status, k.staff_no, k.staff_name, k.organization_code, o.organization_name, k.position_name, k.job_title, k.employment_status, k.retirement_date, k.last_synced_at ORDER BY k.staff_no ASC
